test('totals a simple order', () => {
  assert.deepStrictEqual(invoice([{ name: 'Mug', price: '19.99', qty: 1 }]), ['Mug: 19.99', 'Total: 19.99']);
});

test('prices that are not exact in binary do not lose a cent', () => {
  assert.deepStrictEqual(invoice([{ name: 'Mug', price: '19.99', qty: 1 }]), ['Mug: 19.99', 'Total: 19.99']);
  assert.deepStrictEqual(invoice([{ name: 'Pen', price: '0.29', qty: 3 }]), ['Pen: 0.87', 'Total: 0.87']);
});

test('refund lines print with a single leading minus sign', () => {
  assert.deepStrictEqual(invoice([{ name: 'Refund', price: '-0.50', qty: 1 }]), ['Refund: -0.50', 'Total: -0.50']);
  assert.deepStrictEqual(invoice([{ name: 'Refund', price: '-19.99', qty: 1 }]), ['Refund: -19.99', 'Total: -19.99']);
});

test('percent discount rounds to the nearest cent', () => {
  // 1.15 * 10% = 11.5 cents -> 12 cents off (rounded), total 1.03
  assert.deepStrictEqual(invoice([{ name: 'A', price: '1.15', qty: 1 }], 10), ['A: 1.15', 'Discount: -0.12', 'Total: 1.03']);
});

